    public static void main(String[] args) throws Exception {
        String s = new FastReader().next();
        int n = s.length(), matched = 0;
        for (int i = 0; i < n; i++)  // greedily match the longest prefix of the reversed string
            if (matched < n && s.charAt(i) == s.charAt(n - 1 - matched)) matched++;
